  'fr', 'de', 'ready', 3, 'B1', 'Café in Paris', 'Mardi matin',
  '{"title": "Mardi matin", "sections": [{"sentences": [{"id": "s1", "source": "Hier, je suis allée dans un petit café près du canal.", "native": "Gestern bin ich in ein kleines Café am Kanal gegangen.", "spans": [{"at": 6, "len": 13, "lexeme": "fdeb98b0-2359-58e4-a2be-1b4cd1a88a58", "here": "ich bin gegangen", "nativeMarks": ["bin ich", "gegangen"], "mark": true}, {"at": 34, "len": 4, "lexeme": "36b07e01-ac6f-50fe-a445-e23283196901", "here": "Café", "nativeMarks": ["Café"]}, {"at": 39, "len": 7, "lexeme": "e1a5c7b0-5274-5123-ae77-75902b94ab90", "here": "in der Nähe des", "nativeMarks": ["am"], "mark": true}, {"at": 47, "len": 5, "lexeme": "2db0e0d1-eb90-5eb6-a3f5-9e6a3b3447e3", "here": "Kanal", "nativeMarks": ["Kanal"]}]}, {"id": "s2", "source": "Le serveur m’a demandé si je voulais un crème ou un allongé.", "native": "Der Kellner hat mich gefragt, ob ich einen Milchkaffee oder einen verlängerten Espresso möchte.", "spans": [{"at": 3, "len": 7, "lexeme": "d19e1dca-8baa-5e9c-8b7d-7fba04b0965b", "here": "Kellner", "nativeMarks": ["Kellner"]}, {"at": 11, "len": 11, "lexeme": "948f0def-884a-5e96-9e94-fa22118e7bc1", "here": "hat mich gefragt", "nativeMarks": ["hat mich gefragt"], "mark": true}, {"at": 26, "len": 10, "lexeme": "94bce832-2e79-516a-9d49-4038dc740c0c", "here": "ich wollte", "nativeMarks": ["ich", "möchte"], "mark": true}, {"at": 37, "len": 8, "lexeme": "128834ec-0eb1-5afd-8e6e-c926a18fe1b2", "here": "ein Milchkaffee", "nativeMarks": ["einen Milchkaffee"], "mark": true}, {"at": 49, "len": 10, "lexeme": "9501e7e9-650b-5bb6-8506-a20c6e1b2180", "here": "ein verlängerter Espresso", "nativeMarks": ["einen verlängerten Espresso"]}]}, {"id": "s3", "source": "Je n’ai pas compris tout de suite, alors il a souri et m’a expliqué la différence.", "native": "Ich habe es nicht sofort verstanden, da hat er gelächelt und mir den Unterschied erklärt.", "spans": [{"at": 12, "len": 7, "lexeme": "4c85cbe5-6f4c-584a-a714-aaa4b8f2db2e", "here": "verstanden", "nativeMarks": ["verstanden"]}, {"at": 20, "len": 13, "lexeme": "7aef91c4-2ad7-553a-a787-c4085287a587", "here": "sofort", "nativeMarks": ["sofort"], "mark": true}, {"at": 46, "len": 5, "lexeme": "6c962e5f-69de-5a44-bbdf-68140c0138e4", "here": "gelächelt", "nativeMarks": ["gelächelt"]}, {"at": 59, "len": 8, "lexeme": "dac0282b-322a-5346-9d9e-9e64ec726758", "here": "erklärt", "nativeMarks": ["erklärt"]}, {"at": 71, "len": 10, "lexeme": "9aca3708-d198-55a1-b754-b79114bf0893", "here": "Unterschied", "nativeMarks": ["Unterschied"]}]}, {"id": "s4", "source": "J’ai commandé un allongé et un pain au chocolat.", "native": "Ich habe einen verlängerten Espresso und ein Schokobrötchen bestellt.", "spans": [{"at": 5, "len": 8, "lexeme": "fc1f98b3-62ba-523a-a579-d1d113d317af", "here": "bestellt", "nativeMarks": ["bestellt"]}, {"at": 28, "len": 19, "lexeme": "362a5bad-9d5b-5150-84e5-2087c7eca78d", "here": "ein Schokobrötchen", "nativeMarks": ["ein Schokobrötchen"], "mark": true}]}]}, {"sentences": [{"id": "s5", "source": "Je me suis assise près de la fenêtre et j’ai sorti mon carnet.", "native": "Ich habe mich ans Fenster gesetzt und mein Heft herausgeholt.", "spans": [{"at": 0, "len": 17, "lexeme": "5b1acd24-a04e-5186-b8ed-454c83d25ca7", "here": "ich habe mich gesetzt", "nativeMarks": ["habe mich", "gesetzt"], "mark": true}, {"at": 29, "len": 7, "lexeme": "df6930f5-e748-51af-bc3d-a1f739ff67a7", "here": "Fenster", "nativeMarks": ["Fenster"]}, {"at": 45, "len": 5, "lexeme": "3ce5fde7-6ffc-5efe-b920-b0f37187177a", "here": "herausgeholt", "nativeMarks": ["herausgeholt"]}, {"at": 55, "len": 6, "lexeme": "67a0e8a4-ef01-5915-8afe-bc1f7a5d6378", "here": "Heft", "nativeMarks": ["Heft"], "mark": true}]}, {"id": "s6", "source": "À côté de moi, deux femmes parlaient très vite.", "native": "Neben mir sprachen zwei Frauen sehr schnell.", "spans": [{"at": 0, "len": 9, "lexeme": "79806ee3-327e-5af5-be2d-1fee1eee3c82", "here": "neben", "nativeMarks": ["Neben"], "mark": true}, {"at": 27, "len": 9, "lexeme": "9790ab6e-8d37-5544-9c8b-b122ab3230d6", "here": "sprachen", "nativeMarks": ["sprachen"]}, {"at": 42, "len": 4, "lexeme": "4f1ec03b-2299-528e-a317-8b1259084eda", "here": "schnell", "nativeMarks": ["schnell"], "mark": true}]}, {"id": "s7", "source": "Je n’ai compris qu’un mot sur trois.", "native": "Ich habe nur jedes dritte Wort verstanden.", "spans": [{"at": 8, "len": 7, "lexeme": "4c85cbe5-6f4c-584a-a714-aaa4b8f2db2e", "here": "verstanden", "nativeMarks": ["verstanden"]}, {"at": 22, "len": 3, "lexeme": "f1d3f647-a044-5369-8215-0cbe3ff72a8b", "here": "Wort", "nativeMarks": ["Wort"]}]}, {"id": "s8", "source": "Quand le serveur est revenu, il m’a demandé si tout allait bien.", "native": "Als der Kellner zurückkam, fragte er mich, ob alles in Ordnung sei.", "spans": [{"at": 9, "len": 7, "lexeme": "d19e1dca-8baa-5e9c-8b7d-7fba04b0965b", "here": "Kellner", "nativeMarks": ["Kellner"]}, {"at": 17, "len": 10, "lexeme": "ed04bd8d-dd8f-55b3-b32c-4d61ad145bb2", "here": "zurückkam", "nativeMarks": ["zurückkam"], "mark": true}, {"at": 32, "len": 11, "lexeme": "948f0def-884a-5e96-9e94-fa22118e7bc1", "here": "fragte mich", "nativeMarks": ["fragte er mich"]}]}]}, {"sentences": [{"id": "s9", "source": "J’ai répondu que oui, et que le pain au chocolat était encore chaud.", "native": "Ich habe geantwortet, dass ja, und dass das Schokobrötchen noch warm war.", "spans": [{"at": 5, "len": 7, "lexeme": "aa83e754-e916-57e7-a761-4815c07570e3", "here": "geantwortet", "nativeMarks": ["geantwortet"]}, {"at": 32, "len": 16, "lexeme": "362a5bad-9d5b-5150-84e5-2087c7eca78d", "here": "Schokobrötchen", "nativeMarks": ["Schokobrötchen"]}, {"at": 62, "len": 5, "lexeme": "33a9c48d-03b8-5970-8bd4-2c64cebdb155", "here": "warm", "nativeMarks": ["warm"], "mark": true}]}, {"id": "s10", "source": "Avant de partir, j’ai demandé l’addition.", "native": "Bevor ich ging, habe ich die Rechnung verlangt.", "spans": [{"at": 9, "len": 6, "lexeme": "aec88915-f1b6-5ac9-8190-bf3a16f4d21a", "here": "weggehen", "nativeMarks": ["ging"]}, {"at": 30, "len": 10, "lexeme": "ba265cca-bd3f-5d8b-b57a-6a2bcaa628f5", "here": "die Rechnung", "nativeMarks": ["die Rechnung"], "mark": true}]}, {"id": "s11", "source": "Le serveur a souri : « À demain, peut-être ? »", "native": "Der Kellner lächelte: „Bis morgen, vielleicht?“", "spans": [{"at": 13, "len": 5, "lexeme": "6c962e5f-69de-5a44-bbdf-68140c0138e4", "here": "lächelte", "nativeMarks": ["lächelte"]}, {"at": 25, "len": 6, "lexeme": "6e309060-850e-5dec-bf2d-8c56ad866ba5", "here": "morgen", "nativeMarks": ["morgen"], "mark": true}, {"at": 33, "len": 9, "lexeme": "0ed27d04-3106-5a35-a312-22ec42e1b697", "here": "vielleicht", "nativeMarks": ["vielleicht"], "mark": true}]}]}]}'::jsonb,
